#![allow(dead_code, unused_imports)]
mod capacity {
    #[doc = " Fraction of free device memory the capacity derivation will spend, as"]
    #[doc = " numerator over denominator."]
    #[doc = ""]
    #[doc = " Headroom leaves room for driver allocations and other device users beyond"]
    #[doc = " the session buffers and the explicit pool allowance."]
    pub const MEMORY_HEADROOM_NUM: usize = 4;
    #[doc = " See [`MEMORY_HEADROOM_NUM`]."]
    pub const MEMORY_HEADROOM_DEN: usize = 5;
    #[doc = " Session allowance for CUDA pool growth and allocation overhead."]
    const POOL_ALLOWANCE_BYTES: usize = 32 << 20;
    #[doc = " Device facts the capacity derivation needs, read once at open."]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct DeviceLimits {
        #[doc = " `CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK`."]
        pub shared_bytes_per_block: usize,
        #[doc = " `CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN`. Bounds the prefix,"]
        #[doc = " whose block opts in to more than the default per-block limit."]
        pub shared_bytes_per_block_optin: usize,
        #[doc = " Free device memory at open, from `cuMemGetInfo`. Bounds session buffers."]
        pub free_bytes: usize,
        #[doc = " `CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT`."]
        pub sm_count: usize,
        #[doc = " `CU_DEVICE_ATTRIBUTE_MAX_THREADS_PER_MULTIPROCESSOR`. The driver"]
        #[doc = " reserves local memory for full occupancy, so this multiplies the SA"]
        #[doc = " frame whether or not that many threads ever run."]
        pub threads_per_sm: usize,
    }
    impl DeviceLimits {
        #[doc = " Free memory less the headroom the model does not account for."]
        #[must_use]
        pub fn usable_bytes(&self) -> usize {
            self.free_bytes / MEMORY_HEADROOM_DEN * MEMORY_HEADROOM_NUM
        }
    }
    #[doc = " Device memory shared by the session and repeated for each nonce group."]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct Footprint {
        #[doc = " Session-wide device allocations, including topology and lane tables."]
        #[doc = " This is global memory, distinct from CUDA block shared memory."]
        pub shared_bytes: usize,
        #[doc = " Device memory per concurrent nonce group."]
        pub per_instance_bytes: usize,
        #[doc = " Concurrent nonce groups, derived from the device's SM count."]
        pub instances: usize,
    }
    impl Footprint {
        #[doc = " Total device memory, saturating so oversized shapes cannot wrap to fit."]
        #[must_use]
        pub fn total(&self) -> usize {
            self.shared_bytes
                .saturating_add(self.per_instance_bytes.saturating_mul(self.instances))
        }
    }
    #[doc = " Threads per cluster anneal, matching `gpucluster.cu:272`."]
    pub const CLUSTER_THREADS: usize = 512;
    #[doc = " Shared bytes per node: two int arrays and one byte spin (`gpucluster.cu:139-143`)."]
    pub const CLUSTER_SHARED_BYTES_PER_NODE: usize = 9;
    #[doc = " Dynamic shared padding requested by `gpucluster.cu:322`."]
    pub const CLUSTER_DYNAMIC_PADDING: usize = 16;
    #[doc = " The static `changed` int in `gpucluster.cu:144`."]
    pub const CLUSTER_STATIC_SHARED_BYTES: usize = 4;
    #[doc = " Sizes of the prepared cluster arrays. ELL widths count padded slots per node."]
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct ClusterShape {
        #[doc = " Number of nodes."]
        pub nodes: usize,
        #[doc = " Number of four-node tiles."]
        pub tiles: usize,
        #[doc = " Number of pair links."]
        pub links: usize,
        #[doc = " Maximum nonzero residual degree."]
        pub weak_width: usize,
        #[doc = " Maximum nonzero original degree."]
        pub all_width: usize,
        #[doc = " Number of contiguous color ranges."]
        pub colors: usize,
    }
    #[doc = " Cluster global memory, including explicit fields and both weight arrays."]
    #[doc = ""]
    #[doc = " Counts `gpucluster.cu:298-307` uploads and `309-321` spin and RNG state."]
    #[doc = " Each empty upload reserves one element, as in `gpucluster.cu:259-262`."]
    #[doc = " Permutations and the original graph stay on the host. Parent and component"]
    #[doc = " accumulators occupy block shared memory, not global memory."]
    #[must_use]
    pub fn cluster_footprint(shape: ClusterShape, anneals: usize) -> Footprint {
        let n = shape.nodes;
        let t = shape.tiles;
        let p = shape.links;
        let int_bytes = |count: usize| count.max(1).saturating_mul(4);
        let mut shared = POOL_ALLOWANCE_BYTES;
        for count in [
            t.saturating_mul(4),
            p.saturating_mul(2),
            n,
            n.saturating_mul(shape.weak_width),
            n,
            n.saturating_mul(shape.all_width),
            shape.colors.saturating_add(1),
            n,
            t,
            p,
        ] {
            shared = shared.saturating_add(int_bytes(count));
        }
        shared = shared.saturating_add(t.saturating_mul(4).max(1));
        Footprint {
            shared_bytes: shared,
            per_instance_bytes: n.saturating_add(CLUSTER_THREADS.saturating_mul(8)),
            instances: anneals,
        }
    }
}
mod cuda_device {
    use cudarc::driver::{sys::CUdevice_attribute, CudaContext};
    use thiserror::Error;
    #[doc = " Every GPU architecture the miner supports: the intersection of what NVRTC"]
    #[doc = " 12.9 targets natively (`sm_50..sm_121`, measured via `nvrtcGetSupportedArchs`"]
    #[doc = " 2026-08-14) and what the kernels require — all three call `__nanosleep`, an"]
    #[doc = " `sm_70+` instruction, so the floor is Volta regardless of toolkit."]
    #[doc = ""]
    #[doc = " This is the support contract: `tests/arch_coverage.rs` compiles every"]
    #[doc = " kernel for each entry and assembles the PTX with `ptxas`, so growing or"]
    #[doc = " shrinking this list is a reviewed, CI-checked decision rather than a side"]
    #[doc = " effect of a toolkit bump."]
    pub const SUPPORTED_ARCHS: &[i32] = &[70, 72, 75, 80, 86, 87, 89, 90, 100, 101, 103, 120, 121];
    #[doc = " Highest supported arch at or below the detected compute capability."]
    #[doc = ""]
    #[doc = " Above the ceiling clamps to 121 (PTX loads forward through the driver"]
    #[doc = " JIT); below the floor clamps to 70, where the load then fails at the"]
    #[doc = " driver with a clear per-device error instead of inside NVRTC; a gap value"]
    #[doc = " (e.g. 88, which only CUDA 13 tables know) selects the next lower entry."]
    #[doc = ""]
    #[doc = " This replaces a driver-version fallback table that could select an arch"]
    #[doc = " *newer* than the actual device (r610 driver → `compute_121` on an `sm_86`"]
    #[doc = " card) — and PTX only loads forward, so that open failed with"]
    #[doc = " `CUDA_ERROR_INVALID_PTX`."]
    pub(crate) fn select_arch(cc: i32) -> i32 {
        SUPPORTED_ARCHS
            .iter()
            .copied()
            .filter(|&a| a <= cc)
            .max()
            .unwrap_or(70)
    }
    #[doc = " Detect the device capability and clamp it to the supported compile targets."]
    pub(crate) fn device_arch(ctx: &CudaContext) -> i32 {
        let cc = match (
            ctx.attribute(CUdevice_attribute::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MAJOR),
            ctx.attribute(CUdevice_attribute::CU_DEVICE_ATTRIBUTE_COMPUTE_CAPABILITY_MINOR),
        ) {
            (Ok(major), Ok(minor)) => major * 10 + minor,
            _ => 70,
        };
        select_arch(cc)
    }
    #[doc = " `cuDriverGetVersion`, wrapped safely (cudarc exposes only the raw sys fn)."]
    pub(crate) fn driver_version() -> Result<i32, CudaError> {
        let mut v: std::ffi::c_int = 0;
        unsafe { cudarc::driver::sys::cuDriverGetVersion(std::ptr::from_mut(&mut v)) }.result()?;
        Ok(v)
    }
    #[doc = " Failures from opening a device or compiling its kernels."]
    #[derive(Debug, Error)]
    pub enum CudaError {
        #[doc = " A CUDA driver call failed; the payload is the driver's own message."]
        #[error("CUDA driver: {0}")]
        Driver(String),
        #[doc = " NVRTC rejected the kernel source for the selected architecture."]
        #[error("NVRTC compile: {0}")]
        Compile(String),
        #[doc = " `device_index` is past the number of devices visible to this process."]
        #[error("no CUDA device at index {0}")]
        NoDevice(usize),
    }
    impl From<cudarc::driver::DriverError> for CudaError {
        fn from(e: cudarc::driver::DriverError) -> Self {
            CudaError::Driver(e.to_string())
        }
    }
}
