    #[doc = " The strong tile coupling, in milli. A tile edge between positions `a` and"]
    #[doc = " `b` carries `STRONG_MILLI * g[a] * g[b]`."]
    pub const STRONG_MILLI: i32 = 1000;
    #[doc = " The pair coupling, in milli."]
    pub const PAIR_MILLI: i32 = -1000;
    #[doc = " The explicit Ising model, in milli. Energy is `sum h s + sum J s s`."]
    #[derive(Clone, Copy, Debug)]
    pub struct Model<'a> {
        #[doc = " One field per node. The kernel supports only zero fields."]
        pub h_milli: &'a [i32],
        #[doc = " Each edge once, in either orientation."]
        pub edges: &'a [(u32, u32)],
        #[doc = " One coupling per edge."]
        pub j_milli: &'a [i32],
    }
    #[doc = " The motifs of a gauged-ice instance."]
    #[derive(Clone, Copy, Debug)]
    pub struct Motifs<'a> {
        #[doc = " Four distinct nodes per tile. Tiles may share nodes but not edges."]
        pub tiles: &'a [[u32; 4]],
        #[doc = " The local gauge of each tile, one sign per tile position."]
        pub gauges: &'a [[i8; 4]],
        #[doc = " Node-disjoint pair edges with coupling [`PAIR_MILLI`]."]
        pub pairs: &'a [(u32, u32)],
    }
    #[doc = " How much of each strong coupling the cluster draw handles, in milli. The"]
    #[doc = " remainder joins the weak layer, so the energy does not change."]
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct Weights {
        #[doc = " The pair bond weight, `0..=1000`."]
        pub pair_milli: i32,
        #[doc = " The tile bond weight, `1..=1000`."]
        pub tile_milli: i32,
    }
    impl Weights {
        #[doc = " Every strong coupling in the cluster draw."]
        pub const FULL: Self = Self {
            pair_milli: 1000,
            tile_milli: 1000,
        };
        fn is_valid(self) -> bool {
            (0..=1000).contains(&self.pair_milli) && (1..=1000).contains(&self.tile_milli)
        }
    }
    #[doc = " Why a model and its motifs cannot run on the kernel."]
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum GraphError {
        #[doc = " The model has no nodes."]
        Empty,
        #[doc = " A weight is outside its range."]
        Weights,
        #[doc = " A field is not zero."]
        Fields,
        #[doc = " The edge and coupling counts, or the tile and gauge counts, differ."]
        Lengths,
        #[doc = " An edge end is out of range, the edge is a loop, or `|J| > 1000`."]
        Edge {
            #[doc = " The edge position."]
            index: usize,
        },
        #[doc = " The edge repeats an earlier edge."]
        DuplicateEdge {
            #[doc = " The position of the repeat."]
            index: usize,
        },
        #[doc = " A tile node is out of range or repeated."]
        Tile {
            #[doc = " The tile position."]
            tile: usize,
        },
        #[doc = " A gauge entry is not `1` or `-1`."]
        Gauge {
            #[doc = " The tile position."]
            tile: usize,
        },
        #[doc = " A tile edge is missing or its coupling disagrees with the gauge."]
        TileCoupling {
            #[doc = " The tile position."]
            tile: usize,
        },
        #[doc = " A tile edge already belongs to an earlier tile."]
        TileOverlap {
            #[doc = " The tile position."]
            tile: usize,
        },
        #[doc = " A pair node is out of range or taken, the pair coupling is not"]
        #[doc = " [`PAIR_MILLI`], or the pair edge is a tile edge."]
        Pair {
            #[doc = " The pair position."]
            pair: usize,
        },
        #[doc = " An edge with `|J| = 1000` belongs to no motif."]
        StrongEdge {
            #[doc = " The edge position."]
            index: usize,
        },
    }
    impl fmt::Display for GraphError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            match self {
                Self::Empty => write!(f, "the model has no nodes"),
                Self::Weights => write!(
                    f,
                    "the pair weight must be in 0..=1000 and the tile weight in 1..=1000 milli"
                ),
                Self::Fields => write!(f, "the cluster kernel supports only zero fields"),
                Self::Lengths => write!(f, "edge, coupling, tile, or gauge counts differ"),
                Self::Edge { index } => {
                    write!(f, "edge {index} is out of range or above 1000 milli")
                }
                Self::DuplicateEdge { index } => write!(f, "edge {index} repeats an earlier edge"),
                Self::Tile { tile } => write!(f, "tile {tile} has an invalid or repeated node"),
                Self::Gauge { tile } => {
                    write!(f, "tile {tile} has a gauge entry that is not a sign")
                }
                Self::TileCoupling { tile } => {
                    write!(f, "tile {tile} has an edge that does not match its gauge")
                }
                Self::TileOverlap { tile } => write!(f, "tile {tile} shares an edge with a tile"),
                Self::Pair { pair } => write!(f, "pair {pair} is not a disjoint -1000 milli edge"),
                Self::StrongEdge { index } => write!(f, "edge {index} is strong but in no motif"),
            }
        }
    }
    impl std::error::Error for GraphError {}
    #[derive(Clone, Copy, Debug)]
    struct Tile {
        nodes: [usize; 4],
        gauge: [i8; 4],
    }
    #[doc = " A validated gauged-ice graph split into strong and weak layers."]
    #[derive(Debug)]
    pub struct OtsukaGraph {
        n: usize,
        tiles: Vec<Tile>,
        pairs: Vec<(usize, usize)>,
        weights: Weights,
        #[doc = " Every coupling of the model."]
        edges: Vec<Edge>,
        #[doc = " The weak layer: non-motif edges plus the residuals of soft weights."]
        weak_edges: Vec<Edge>,
    }
    #[doc = " An edge and its coupling in milli."]
    type Edge = (usize, usize, i32);
    #[doc = " The edge position of each unordered node pair."]
    type EdgeIndex = HashMap<(usize, usize), usize>;
    fn key(u: usize, v: usize) -> (usize, usize) {
        (u.min(v), u.max(v))
    }
    fn node(id: u32, n: usize) -> Option<usize> {
        usize::try_from(id).ok().filter(|&u| u < n)
    }
    fn check_edges(model: &Model<'_>, n: usize) -> Result<(Vec<Edge>, EdgeIndex), GraphError> {
        let mut edges = Vec::with_capacity(model.edges.len());
        let mut index = EdgeIndex::with_capacity(model.edges.len());
        for (at, (&(u, v), &j)) in model.edges.iter().zip(model.j_milli).enumerate() {
            let (Some(u), Some(v)) = (node(u, n), node(v, n)) else {
                return Err(GraphError::Edge { index: at });
            };
            if u == v || !(-STRONG_MILLI..=STRONG_MILLI).contains(&j) {
                return Err(GraphError::Edge { index: at });
            }
            if index.insert(key(u, v), at).is_some() {
                return Err(GraphError::DuplicateEdge { index: at });
            }
            edges.push((u, v, j));
        }
        Ok((edges, index))
    }
    #[doc = " Check each tile and mark its edges in `strong`."]
    fn check_tiles(
        motifs: &Motifs<'_>,
        n: usize,
        edges: &[Edge],
        index: &EdgeIndex,
        strong: &mut [bool],
    ) -> Result<Vec<Tile>, GraphError> {
        let mut tiles = Vec::with_capacity(motifs.tiles.len());
        for (tile, (ids, &gauge)) in motifs.tiles.iter().zip(motifs.gauges).enumerate() {
            let mut nodes = [0; 4];
            for (slot, &id) in nodes.iter_mut().zip(ids) {
                *slot = node(id, n).ok_or(GraphError::Tile { tile })?;
            }
            if (0..4).any(|a| (a + 1..4).any(|b| nodes[a] == nodes[b])) {
                return Err(GraphError::Tile { tile });
            }
            if gauge.iter().any(|&g| g != 1 && g != -1) {
                return Err(GraphError::Gauge { tile });
            }
            for a in 0..4 {
                for b in a + 1..4 {
                    let want = STRONG_MILLI * i32::from(gauge[a] * gauge[b]);
                    let at = *index
                        .get(&key(nodes[a], nodes[b]))
                        .ok_or(GraphError::TileCoupling { tile })?;
                    if edges[at].2 != want {
                        return Err(GraphError::TileCoupling { tile });
                    }
                    if std::mem::replace(&mut strong[at], true) {
                        return Err(GraphError::TileOverlap { tile });
                    }
                }
            }
            tiles.push(Tile { nodes, gauge });
        }
        Ok(tiles)
    }
    #[doc = " Check each pair and mark its edge in `strong`."]
    fn check_pairs(
        motifs: &Motifs<'_>,
        n: usize,
        edges: &[Edge],
        index: &EdgeIndex,
        strong: &mut [bool],
    ) -> Result<Vec<(usize, usize)>, GraphError> {
        let mut taken = vec![false; n];
        let mut pairs = Vec::with_capacity(motifs.pairs.len());
        for (pair, &(u, v)) in motifs.pairs.iter().enumerate() {
            let bad = GraphError::Pair { pair };
            let (Some(u), Some(v)) = (node(u, n), node(v, n)) else {
                return Err(bad);
            };
            if u == v || taken[u] || taken[v] {
                return Err(bad);
            }
            let at = *index.get(&key(u, v)).ok_or(bad)?;
            if edges[at].2 != PAIR_MILLI || std::mem::replace(&mut strong[at], true) {
                return Err(bad);
            }
            taken[u] = true;
            taken[v] = true;
            pairs.push((u, v));
        }
        Ok(pairs)
    }
    impl OtsukaGraph {
        #[doc = " Validate `model` against `motifs` and split its couplings."]
        #[doc = ""]
        #[doc = " # Errors"]
        #[doc = ""]
        #[doc = " Returns the first validation error before any sampling work."]
        pub fn new(
            model: &Model<'_>,
            motifs: &Motifs<'_>,
            weights: Weights,
        ) -> Result<Self, GraphError> {
            let n = model.h_milli.len();
            if n == 0 {
                return Err(GraphError::Empty);
            }
            if !weights.is_valid() {
                return Err(GraphError::Weights);
            }
            if model.h_milli.iter().any(|&h| h != 0) {
                return Err(GraphError::Fields);
            }
            if model.edges.len() != model.j_milli.len() || motifs.tiles.len() != motifs.gauges.len()
            {
                return Err(GraphError::Lengths);
            }
            let (edges, index) = check_edges(model, n)?;
            let mut strong = vec![false; edges.len()];
            let tiles = check_tiles(motifs, n, &edges, &index, &mut strong)?;
            let pairs = check_pairs(motifs, n, &edges, &index, &mut strong)?;
            let mut weak_edges = Vec::new();
            for (at, (&edge, &is_strong)) in edges.iter().zip(&strong).enumerate() {
                if is_strong {
                    continue;
                }
                if edge.2.abs() >= STRONG_MILLI {
                    return Err(GraphError::StrongEdge { index: at });
                }
                weak_edges.push(edge);
            }
            let pair_residual = weights.pair_milli - 1000;
            if pair_residual != 0 {
                weak_edges.extend(pairs.iter().map(|&(u, v)| (u, v, pair_residual)));
            }
            let tile_residual = 1000 - weights.tile_milli;
            if tile_residual != 0 {
                for tile in &tiles {
                    for a in 0..4 {
                        for b in a + 1..4 {
                            let j = tile_residual * i32::from(tile.gauge[a] * tile.gauge[b]);
                            weak_edges.push((tile.nodes[a], tile.nodes[b], j));
                        }
                    }
                }
            }
            Ok(Self {
                n,
                tiles,
                pairs,
                weights,
                edges,
                weak_edges,
            })
        }
        #[doc = " The number of nodes."]
        #[must_use]
        pub fn num_nodes(&self) -> usize {
            self.n
        }
        #[doc = " The model energy of `s`, in milli."]
        #[must_use]
        pub fn energy(&self, s: &[i8]) -> i64 {
            self.edges
                .iter()
                .map(|&(u, v, j)| i64::from(j) * i64::from(s[u] * s[v]))
                .sum()
        }
        #[doc = " The energy of the strong layer at the graph's weights, in milli."]
        #[must_use]
        pub fn strong_energy(&self, s: &[i8]) -> i64 {
            let tile_milli = i64::from(self.weights.tile_milli);
            let tiles: i64 = self
                .tiles
                .iter()
                .map(|tile| {
                    let q: i64 = (0..4)
                        .map(|k| i64::from(tile.gauge[k] * s[tile.nodes[k]]))
                        .sum();
                    tile_milli * (q * q - 4) / 2
                })
                .sum();
            let pairs: i64 = self
                .pairs
                .iter()
                .map(|&(u, v)| i64::from(self.weights.pair_milli) * i64::from(s[u] * s[v]))
                .sum();
            tiles - pairs
        }
        #[doc = " The energy of the weak layer, in milli: the model energy less the"]
        #[doc = " strong layer."]
        #[must_use]
        pub fn weak_energy(&self, s: &[i8]) -> i64 {
            self.energy(s) - self.strong_energy(s)
        }
    }
