mod jit_cache {
    use crate::cuda_device::CudaError;
    use cudarc::driver::{CudaContext, CudaModule};
    use cudarc::nvrtc::Ptx;
    use std::collections::hash_map::DefaultHasher;
    use std::ffi::OsString;
    use std::hash::{Hash, Hasher};
    use std::path::PathBuf;
    use std::sync::Arc;
    use std::time::Instant;
    use tracing::{info, warn};
    #[doc = " Marker for the NVRTC flag set the PTX was produced with. Folded into the"]
    #[doc = " cache key so a change to the compile flags invalidates every stored entry."]
    #[doc = " `compile_with_fallback` always passes `use_fast_math`; the fallback's"]
    #[doc = " `--gpu-architecture=compute_N` is a deterministic function of the driver"]
    #[doc = " version, which is already part of the key."]
    const FLAGS_TAG: &str = "ffm";
    #[doc = " Resolve the base cache directory from the given environment values, without"]
    #[doc = " touching the real process environment (so it is unit-testable)."]
    #[doc = ""]
    #[doc = " Precedence: `QUIP_CUDA_CACHE` (used verbatim) → `XDG_CACHE_HOME` +"]
    #[doc = " `/quip-solver-cuda` → `HOME` + `/.cache/quip-solver-cuda`. Returns `None` when"]
    #[doc = " none resolve to a non-empty path."]
    fn resolve_cache_dir(
        quip: Option<OsString>,
        xdg: Option<OsString>,
        home: Option<OsString>,
    ) -> Option<PathBuf> {
        fn non_empty(v: Option<OsString>) -> Option<PathBuf> {
            v.filter(|s| !s.is_empty()).map(PathBuf::from)
        }
        if let Some(dir) = non_empty(quip) {
            return Some(dir);
        }
        if let Some(dir) = non_empty(xdg) {
            return Some(dir.join("quip-solver-cuda"));
        }
        non_empty(home).map(|h| h.join(".cache").join("quip-solver-cuda"))
    }
    #[doc = " Resolve and create the cache directory, reading the real environment."]
    #[doc = " Returns `None` when the directory cannot be resolved or created (caching is"]
    #[doc = " then skipped, never fatal)."]
    fn cache_dir() -> Option<PathBuf> {
        let dir = resolve_cache_dir(
            std::env::var_os("QUIP_CUDA_CACHE"),
            std::env::var_os("XDG_CACHE_HOME"),
            std::env::var_os("HOME"),
        )?;
        match std::fs::create_dir_all(&dir) {
            Ok(()) => Some(dir),
            Err(e) => {
                warn!("cuda jit cache: cannot create {}: {e}", dir.display());
                None
            }
        }
    }
    #[doc = " `QUIP_CUDA_CACHE_DISABLE` escape hatch: force recompile (skip read + write)."]
    fn cache_disabled() -> bool {
        std::env::var("QUIP_CUDA_CACHE_DISABLE")
            .ok()
            .is_some_and(|v| !v.is_empty() && v != "0")
    }
    #[doc = " Cache key / filename stem for one kernel. Same"]
    #[doc = " `(src, defines, arch, driver_version, max_nodes)` yields the same key;"]
    #[doc = " different source or defines yield a different key. `arch`, `driver_version`"]
    #[doc = " and `max_nodes` appear verbatim in the stem (readable + they partition the"]
    #[doc = " cache); the source text, defines and flag set are folded into the trailing hash."]
    #[doc = ""]
    #[doc = " `max_nodes` is part of the key because it is a `-D QUIP_MAX_NODES` on the"]
    #[doc = " NVRTC compile: like the other defines, it changes the emitted PTX without"]
    #[doc = " changing `src`. Omitting it would serve a PTX built for a small state array"]
    #[doc = " to a run that needs a large one, and the kernel would write past the array"]
    #[doc = " with no error."]
    fn cache_key(
        kernel: &str,
        src: &str,
        defines: &[&str],
        arch: &str,
        driver_version: i32,
        max_nodes: usize,
    ) -> String {
        let mut h = DefaultHasher::new();
        src.hash(&mut h);
        defines.hash(&mut h);
        FLAGS_TAG.hash(&mut h);
        max_nodes.hash(&mut h);
        let src_hash = h.finish();
        format!("{kernel}-{arch}-drv{driver_version}-n{max_nodes}-{src_hash:016x}")
    }
    #[doc = " Write `text` to `<dir>/<key>.ptx` atomically: write a pid-scoped temp file,"]
    #[doc = " then rename it into place so concurrent processes never observe a partial"]
    #[doc = " file. Non-fatal — a write failure only forgoes the cache."]
    fn write_atomic(dir: &std::path::Path, key: &str, text: &str) {
        let final_path = dir.join(format!("{key}.ptx"));
        let tmp = dir.join(format!("{key}.ptx.tmp.{}", std::process::id()));
        if let Err(e) = std::fs::write(&tmp, text) {
            warn!("cuda jit cache: write {} failed: {e}", tmp.display());
            return;
        }
        if let Err(e) = std::fs::rename(&tmp, &final_path) {
            warn!(
                "cuda jit cache: rename into {} failed: {e}",
                final_path.display()
            );
            drop(std::fs::remove_file(&tmp));
        }
    }
    #[doc = " Load a kernel module from cached PTX, or compile it and cache the result."]
    #[doc = ""]
    #[doc = " Behaviour:"]
    #[doc = " 1. If caching is enabled and `<dir>/<key>.ptx` loads into a module, use it."]
    #[doc = " 2. Otherwise compile via `compile` (NVRTC), load the module, and write the"]
    #[doc = "    PTX to the cache atomically."]
    #[doc = " 3. A cached file that fails to load (corrupt / incompatible) is not fatal:"]
    #[doc = "    the kernel is recompiled and the cache overwritten."]
    #[doc = ""]
    #[doc = " # Errors"]
    #[doc = ""]
    #[doc = " [`CudaError`] only from `compile` (NVRTC) or the module load of freshly"]
    #[doc = " compiled PTX — never from cache I/O, which degrades to a recompile."]
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn load_or_compile<F>(
        ctx: &Arc<CudaContext>,
        kernel: &str,
        src: &str,
        defines: &[&str],
        arch: &str,
        driver_version: i32,
        max_nodes: usize,
        compile: F,
    ) -> Result<Arc<CudaModule>, CudaError>
    where
        F: FnOnce() -> Result<Ptx, CudaError>,
    {
        let key = cache_key(kernel, src, defines, arch, driver_version, max_nodes);
        let dir = if cache_disabled() { None } else { cache_dir() };
        if let Some(dir) = &dir {
            let path = dir.join(format!("{key}.ptx"));
            if let Ok(text) = std::fs::read_to_string(&path) {
                match ctx.load_module(Ptx::from_src(text)) {
                    Ok(module) => {
                        info!("cuda kernel {kernel}: loaded cached PTX ({key})");
                        return Ok(module);
                    }
                    Err(e) => {
                        warn!("cuda kernel {kernel}: cached PTX unusable ({e}); recompiling");
                    }
                }
            }
        }
        let start = Instant::now();
        let ptx = compile()?;
        let text = ptx.to_src();
        let module = ctx.load_module(ptx)?;
        let ms = start.elapsed().as_millis();
        if let Some(dir) = &dir {
            write_atomic(dir, &key, &text);
            info!("cuda kernel {kernel}: compiled + cached PTX ({key}) in {ms}ms");
        } else {
            info!("cuda kernel {kernel}: compiled PTX ({key}) in {ms}ms (cache off)");
        }
        Ok(module)
    }
}
