        #[doc = " use quip_solver_cuda::nvml_gov::UtilGovernor;"]
        #[doc = ""]
        #[doc = " let gov = UtilGovernor::start(\"00000000:00:00.0\", 90, true);"]
        #[doc = ""]
        #[doc = " gov.reconfigure(0, false);"]
        #[doc = " assert_eq!(gov.utilization_ceiling(), 1);"]
        #[doc = " assert!(!gov.yielding());"]
