        #[doc = " ```"]
        #[doc = " use quip_solver_cuda::nvml_gov::UtilGovernor;"]
        #[doc = ""]
        #[doc = " let gov = UtilGovernor::start(\"00000000:00:00.0\", 50, false);"]
        #[doc = " assert!(!gov.should_throttle());"]
