        fn bitset_predictor_matches_actual_elimination_on_signed_graphs() {
            for seed in 0..64 {
                let n = 10;
                let mut adj = vec![Vec::new(); n];
                let mut j = BTreeMap::new();
                for u in 0..n {
                    for v in u + 1..n {
                        if (u * 17 + v * 31 + seed * 13) % 5 < 2 {
                            adj[u].push(v);
                            adj[v].push(u);
                            j.insert((u, v), if (u + v + seed) % 2 == 0 { 37 } else { -53 });
                        }
                    }
                }
                let nodes = (0..n).collect::<Vec<_>>();
                let expected = patch_work(&adj, &nodes).unwrap();
                let solution = exact(&vec![11; n], &j, &|| false).unwrap().unwrap();
                assert_eq!(expected, (solution.width, solution.entries));
            }
        }
