    #[cfg(test)]
    mod validated_donor_energy_tests {
        use super::*;
        #[test]
        fn checked_zero_field_donor_energy_matches_normalized_projection_in_both_gauges() {
            let n = 6;
            let edges = vec![
                (0, 1, 19),
                (1, 0, -7),
                (1, 2, -31),
                (2, 3, 23),
                (3, 4, -17),
                (4, 5, 29),
                (0, 5, 13),
                (3, 3, 101),
            ];
            let model = StrongFusion {
                h: vec![0; n],
                physical_adj: Vec::new(),
                sparse_projection: false,
                edges,
                strong: vec![vec![1], vec![0, 2], vec![1], vec![4], vec![3, 5], vec![4]],
                dimer_edges: BTreeSet::new(),
                bridge_refinement: false,
            };
            let mut reversed = 0;
            for base_bits in 0..64 {
                let base = (0..n)
                    .map(|u| if base_bits >> u & 1 == 0 { -1 } else { 1 })
                    .collect::<Vec<i8>>();
                let base_energy = model.energy(&base).unwrap();
                for donor_bits in 0..64 {
                    let spins = (0..n)
                        .map(|u| if donor_bits >> u & 1 == 0 { -1 } else { 1 })
                        .collect::<Vec<i8>>();
                    let donor = SamplerResult {
                        energy_milli: model.energy(&spins).unwrap(),
                        spins,
                    };
                    model.checked(&donor).unwrap();
                    let mut normalized = donor.spins.clone();
                    if base.iter().zip(&normalized).filter(|(a, b)| a != b).count() > n / 2 {
                        for s in &mut normalized {
                            *s = -*s;
                        }
                        reversed += 1;
                    }
                    assert_eq!(model.energy(&normalized).unwrap(), donor.energy_milli);
                    let (labels, groups) = model.components(&base, &normalized);
                    let (fields, _) = model.project(&base, &labels, groups.len());
                    assert_eq!(
                        donor.energy_milli,
                        base_energy - 2 * fields.iter().sum::<i64>()
                    );
                }
            }
            assert!(reversed > 0);
        }
    }
