        fn checked(model: &StrongFusion, bits: usize) -> SamplerResult {
            let spins = (0..6)
                .map(|u| if bits >> u & 1 == 0 { -1 } else { 1 })
                .collect::<Vec<i8>>();
            SamplerResult {
                energy_milli: model.energy(&spins).unwrap(),
                spins,
            }
        }
        #[test]
        fn parallel_frozen_donor_evaluation_preserves_every_result_tie_and_work_count() {
            let model = fixture();
            let mut donors = Vec::new();
            for bits in 0..64 {
                let read = checked(&model, bits);
                donors.push(read.clone());
                donors.push(SamplerResult {
                    energy_milli: read.energy_milli,
                    spins: read.spins.iter().map(|&s| -s).collect(),
                });
            }
            for bits in 0..64 {
                let parent = checked(&model, bits);
                let (a, sa) = model
                    .improve_sequential_with_stats(&parent, &donors, &|| false, false)
                    .unwrap();
                let (b, sb) = model
                    .improve_parallel_with_stats(&parent, &donors, &|| false)
                    .unwrap();
                assert_eq!(
                    a.map(|r| (r.energy_milli, r.spins)),
                    b.map(|r| (r.energy_milli, r.spins))
                );
                assert_eq!(
                    serde_json::to_value(sa).unwrap(),
                    serde_json::to_value(sb).unwrap()
                );
            }
        }
