        #[test]fn reference_orientations_touch_both_models_and_admit_the_pinned_reference(){let a=vec![-3,2,-5,7,4,-6];let pairs=(0..6).flat_map(|u|(u+1..6).map(move|v|((u,v),((u*11+v*3)%17)as i64-8))).collect::<BTreeMap<_,_>>();for guide in 1..63usize{let mut order=(0..6).collect::<Vec<_>>();order.sort_by_key(|&u|((guide>>u&1)==0,u));let mut rank=vec![0;6];for(i,&u)in order.iter().enumerate(){rank[u]=i;}let anchor=(0..6).find(|&u|guide>>u&1!=0).unwrap();let root=(0..6).find(|&u|guide>>u&1==0).unwrap();let(_,upper,_) =oriented_cut_step(&a,&pairs,&rank,&[(root,0),(anchor,1)],&||false).unwrap();assert!(upper<=value(&a,&pairs,guide));let at_guide=a.iter().enumerate().filter(|&(u,_)|guide>>u&1!=0).map(|(_,v)|v).sum::<i64>()+pairs.iter().map(|(&(u,v),&b)|if b>0{b*((guide>>if rank[u]>rank[v]{u}else{v})&1)as i64}else{b*((guide>>u)&1)as i64*((guide>>v)&1)as i64}).sum::<i64>();assert_eq!(at_guide,value(&a,&pairs,guide));}}
        #[test]fn oriented_pinned_cuts_match_exhaustive_upper_models_and_original_scores(){for seed in 0..128usize{let n=7;let a=(0..n).map(|u|((seed*7+u*11)%31)as i64-15).collect::<Vec<_>>();let pairs=(0..n).flat_map(|u|(u+1..n).map(move|v|((u,v),((seed*11+u*7+v*3)%27)as i64-13))).collect::<BTreeMap<_,_>>();let rank=(0..n).map(|u|(u+seed)%n).collect::<Vec<_>>();for pins in [vec![],vec![(0,0),(1,1)]]{let(delta,upper,selected)=oriented_cut_step(&a,&pairs,&rank,&pins,&||false).unwrap();let code=selected.iter().enumerate().fold(0usize,|m,(u,&s)|m|(usize::from(s)<<u));assert_eq!(delta,value(&a,&pairs,code));let upper_score=|b:usize|a.iter().enumerate().map(|(u,&a)|a*((b>>u)&1)as i64).sum::<i64>()+pairs.iter().map(|(&(u,v),&w)|if w<=0{w*((b>>u)&1)as i64*((b>>v)&1)as i64}else{w*((b>>if rank[u]>rank[v]{u}else{v})&1)as i64}).sum::<i64>();let exact=(0..1usize<<n).filter(|&b|pins.iter().all(|&(u,s)|(b>>u)&1==usize::from(s))).map(upper_score).min().unwrap();assert_eq!(upper,exact);assert!(delta<=upper);for b in 0..1usize<<n{assert!(value(&a,&pairs,b)<=upper_score(b));}if pins.is_empty(){assert!(upper<=0);}}}}
