            let mut spins=initial.spins.clone();let mut energy=initial.energy_milli;let mut fields=self.h.clone();let mut weak=self.h.clone();let mut adj=vec![Vec::new();n];let mut wadj=vec![Vec::new();n];let mut weak_energy=self.h.iter().zip(&spins).map(|(&h,&s)|h*i64::from(s)).sum::<i64>();
