                    let mut spins=initial.spins.clone();for(bit,&id)in ids.iter().enumerate(){if code>>bit&1!=0{for &u in &self.moves[id]{spins[u]=-spins[u];}}}
                    let energy=self.score(&spins)?;if energy!=initial.energy_milli+delta{return Err("Walsh winner original H mismatch".into());}
