            fn xor(a:&[usize],b:&[usize])->Vec<usize>{let(mut i,mut j)=(0,0);let mut out=Vec::new();while i<a.len()||j<b.len(){if j==b.len()||(i<a.len()&&a[i]<b[j]){out.push(a[i]);i+=1;}else if i==a.len()||b[j]<a[i]{out.push(b[j]);j+=1;}else{i+=1;j+=1;}}out}
