        #[test]
        fn chain_span_choices_match_independent_physical_scores_and_reach_full_rank(){
            let groups=(1..64usize).map(|mask|(0..6).filter(|&u|mask>>u&1!=0).collect::<Vec<_>>()).collect();let edges=(0..6).flat_map(|u|(u+1..6).map(move|v|(u,v,if (u+v)%3==0{1000}else if (u+v)%3==1{-1000}else{45}))).collect();let model=Model::build(vec![7,-3,11,5,-9,13],edges,groups).unwrap();let masks=model.moves.iter().map(|nodes|vec![nodes.iter().fold(0u64,|m,&u|m|(1u64<<u))]).collect::<Vec<_>>();let strong=|s:&[i8]|model.original.iter().filter(|e|e.2.abs()>=1000).map(|&(u,v,j)|j*i64::from(s[u])*i64::from(s[v])).sum::<i64>();
            let optimum=(0..64usize).map(|code|model.score(&spin(code,6)).unwrap()).min().unwrap();
            for code in 0..16usize{let initial=spin(code,6);let costs=model.costs(&initial);let native=costs.iter().zip(&model.features).map(|(&c,f)|if f.weight.abs()>=1000{c}else{0}).collect::<Vec<_>>();let ids=model.chain_span(0,&costs,&native,&model.deltas(&costs),&model.deltas(&native),&masks).unwrap();assert_eq!(ids.len(),6);let mut current=initial.clone();for &u in &model.moves[ids[0]]{current[u]=-current[u];}let mut span=BTreeSet::from([0u64,masks[ids[0]][0]]);
                for &chosen in &ids[1..]{let expected=(0..model.moves.len()).filter(|&m|!span.contains(&masks[m][0])).min_by_key(|&m|{let mut child=current.clone();for &u in &model.moves[m]{child[u]=-child[u];}(strong(&child)-strong(&current),model.score(&child).unwrap()-model.score(&current).unwrap(),model.moves[m].len(),m)}).unwrap();assert_eq!(chosen,expected);let extra=span.iter().map(|&v|v^masks[chosen][0]).collect::<Vec<_>>();span.extend(extra);for &u in &model.moves[chosen]{current[u]=-current[u];}}
                assert_eq!(span.len(),64);let values=model.subspace_spectrum(&costs,&ids).unwrap();assert_eq!(model.score(&initial).unwrap()+values.iter().min().unwrap()-values[0],optimum);
            }
        }
