    #[cfg(test)]
    mod triple_tests {
        use super::*;
        #[test]
        fn disjoint_triple_formula_matches_all_states_with_fields_parallel_and_self_terms() {
            let model = Model::build(
                vec![3, -5, 7, -11, 13, -17],
                vec![
                    (0, 1, 19),
                    (1, 2, -31),
                    (0, 3, 17),
                    (2, 4, 23),
                    (4, 5, -29),
                    (3, 5, 37),
                    (1, 0, -7),
                    (5, 5, 101),
                ],
                [vec![0, 3], vec![1, 4], vec![2, 5]].into_iter().collect(),
            )
            .unwrap();
            for bits in 0..64 {
                let s = (0..6)
                    .map(|u| if bits >> u & 1 == 0 { -1 } else { 1 })
                    .collect::<Vec<i8>>();
                let costs = model.costs(&s);
                let d = model.deltas(&costs);
                let mut child = s.clone();
                for group in &model.moves {
                    for &u in group {
                        child[u] = -child[u];
                    }
                }
                let predicted = d.iter().sum::<i64>()
                    + model.correction(0, 1, &costs)
                    + model.correction(0, 2, &costs)
                    + model.correction(1, 2, &costs);
                assert_eq!(
                    model.score(&child).unwrap() - model.score(&s).unwrap(),
                    predicted
                );
            }
        }
        #[test]
        fn exact_negative_wedges_find_a_barrier_that_no_pair_can_cross() {
            let model = Model::build(
                vec![10; 3],
                vec![(0, 1, -12), (1, 2, -12), (0, 2, -12)],
                (0..3).map(|u| vec![u]).collect(),
            )
            .unwrap();
            let s = vec![1; 3];
            let costs = model.costs(&s);
            let deltas = model.deltas(&costs);
            let mut stats = Stats::default();
            assert!(deltas.iter().all(|&d| d > 0));
            assert_eq!(
                model
                    .best_pair(&costs, &deltas, &mut stats, &|| false)
                    .unwrap(),
                None
            );
            assert_eq!(
                model
                    .best_disjoint_triple(&costs, &deltas, &mut stats, &|| false)
                    .unwrap(),
                Some((-60, 0, 1, 2))
            );
            assert_eq!(stats.triple_exact_candidates, 1);
        }
        #[test]
        fn wedge_pruning_matches_exhaustive_disjoint_triples_at_pair_minima() {
            let groups = (1..64)
                .map(|mask| (0..6).filter(|&u| mask >> u & 1 != 0).collect::<Vec<_>>())
                .filter(|g| g.len() <= 2)
                .collect();
            let model = Model::build(
                vec![3, -5, 7, -11, 13, -17],
                vec![
                    (0, 1, -23),
                    (1, 2, -31),
                    (2, 3, -29),
                    (3, 4, -19),
                    (4, 5, -37),
                    (0, 5, -17),
                    (0, 2, 11),
                    (1, 4, 7),
                ],
                groups,
            )
            .unwrap();
            let mut checked = 0;
            for bits in 0..64 {
                let s = (0..6)
                    .map(|u| if bits >> u & 1 == 0 { -1 } else { 1 })
                    .collect::<Vec<i8>>();
                let costs = model.costs(&s);
                let deltas = model.deltas(&costs);
                if deltas.iter().any(|&d| d < 0) {
                    continue;
                }
                let mut stats = Stats::default();
                if model
                    .best_pair(&costs, &deltas, &mut stats, &|| false)
                    .unwrap()
                    .is_some()
                {
                    continue;
                }
                let sparse = model
                    .best_disjoint_triple(&costs, &deltas, &mut stats, &|| false)
                    .unwrap();
                let mut exhaustive = None;
                for a in 0..model.moves.len() {
                    for b in a + 1..model.moves.len() {
                        if !Model::disjoint(&model.moves[a], &model.moves[b]) {
                            continue;
                        }
                        for c in b + 1..model.moves.len() {
                            if !Model::disjoint(&model.moves[a], &model.moves[c])
                                || !Model::disjoint(&model.moves[b], &model.moves[c])
                            {
                                continue;
                            }
                            let mut child = s.clone();
                            for &u in model.moves[a]
                                .iter()
                                .chain(&model.moves[b])
                                .chain(&model.moves[c])
                            {
                                child[u] = -child[u];
                            }
                            let delta = model.score(&child).unwrap() - model.score(&s).unwrap();
                            let candidate = (delta, a, b, c);
                            if delta < 0 && exhaustive.is_none_or(|old| candidate < old) {
                                exhaustive = Some(candidate);
                            }
                        }
                    }
                }
                assert_eq!(sparse, exhaustive);
                checked += 1;
            }
            assert!(checked > 0);
        }
    }
    #[cfg(test)]
    mod gene_packet_tests {
        use super::*;
        #[test]
        fn compatible_multi_parent_packet_crosses_a_four_gene_barrier_beyond_triples() {
            let mut h = vec![0; 20];
            let mut edges = Vec::new();
            let genes = (0..4)
                .map(|a| (5 * a..5 * a + 5).collect::<Vec<_>>())
                .collect::<Vec<_>>();
            for group in &genes {
                h[group[0]] = 4;
                for i in 0..4 {
                    edges.push((group[i], group[i + 1], -1000));
                }
            }
            for a in 0..4 {
                edges.push((genes[a][0], genes[(a + 1) % 4][0], -12));
            }
            let model = Model::build(h, edges, genes.into_iter().collect()).unwrap();
            let s = vec![1; 20];
            let costs = model.costs(&s);
            let deltas = model.deltas(&costs);
            let mut stats = Stats::default();
            assert_eq!(
                model
                    .best_pair(&costs, &deltas, &mut stats, &|| false)
                    .unwrap(),
                None
            );
            assert_eq!(
                model
                    .best_disjoint_triple(&costs, &deltas, &mut stats, &|| false)
                    .unwrap(),
                None
            );
            let result = model
                .best_gene_packet(
                    &costs,
                    &deltas,
                    &(0..4).collect::<Vec<_>>(),
                    &mut stats,
                    &|| false,
                )
                .unwrap()
                .unwrap();
            assert_eq!(result, (-32, vec![0, 1, 2, 3]));
            let mut child = s.clone();
            for id in result.1 {
                for &u in &model.moves[id] {
                    child[u] = -child[u];
                }
            }
            assert_eq!(model.score(&child).unwrap() - model.score(&s).unwrap(), -32);
            assert!(stats.packets_solved > 0);
        }
    }
    #[cfg(test)]
    mod sparse_packet_tests {
        use super::*;
        #[test]
        fn sparse_packets_match_legacy_packets_on_identical_small_families() {
            for fixture in 0..32 {
                let n = 8;
                let mut h = vec![0; 5 * n];
                let mut edges = Vec::new();
                let groups = (0..n)
                    .map(|a| (5 * a..5 * a + 5).collect::<Vec<_>>())
                    .collect::<Vec<_>>();
                for (a, group) in groups.iter().enumerate() {
                    h[group[0]] = (a * 7 + fixture * 11) as i64 % 19 - 9;
                    for i in 0..4 {
                        edges.push((group[i], group[i + 1], -1000));
                    }
                }
                for a in 0..n {
                    for b in a + 1..n {
                        edges.push((
                            groups[a][0],
                            groups[b][0],
                            ((a * 13 + b * 17 + fixture * 7) % 23) as i64 - 11,
                        ));
                    }
                }
                let model = Model::build(h, edges, groups.into_iter().collect()).unwrap();
                let costs = model.costs(&vec![1; 5 * n]);
                let deltas = model.deltas(&costs);
                let genes = (0..n).collect::<Vec<_>>();
                let mut dense = Stats::default();
                let mut sparse = Stats::default();
                let a = model
                    .best_gene_packet(&costs, &deltas, &genes, &mut dense, &|| false)
                    .unwrap();
                let b = model
                    .best_sparse_gene_packet(&costs, &deltas, &genes, &mut sparse, &|| false)
                    .unwrap();
                assert_eq!(a, b);
                assert_eq!(dense.packets_solved, sparse.packets_solved);
                assert_eq!(dense.packet_table_entries, sparse.packet_table_entries);
                assert_eq!(
                    dense.packet_duplicate_packings,
                    sparse.packet_duplicate_packings
                );
            }
        }
        #[test]
        fn a_large_sparse_pool_solves_small_four_gene_barriers_without_dense_cap() {
            let n = 132;
            let mut h = vec![0; 5 * n];
            let mut edges = Vec::new();
            let groups = (0..n)
                .map(|a| (5 * a..5 * a + 5).collect::<Vec<_>>())
                .collect::<Vec<_>>();
            for group in &groups {
                h[group[0]] = 4;
                for i in 0..4 {
                    edges.push((group[i], group[i + 1], -1000));
                }
            }
            for base in (0..n).step_by(4) {
                for i in 0..4 {
                    edges.push((groups[base + i][0], groups[base + (i + 1) % 4][0], -12));
                }
            }
            let model = Model::build(h, edges, groups.into_iter().collect()).unwrap();
            let s = vec![1; 5 * n];
            let costs = model.costs(&s);
            let deltas = model.deltas(&costs);
            let genes = (0..n).collect::<Vec<_>>();
            let mut stats = Stats::default();
            let result = model
                .best_sparse_gene_packet(&costs, &deltas, &genes, &mut stats, &|| false)
                .unwrap()
                .unwrap();
            assert_eq!(result, (-32, vec![0, 1, 2, 3]));
            assert!(!stats.packet_pool_capped);
            assert_eq!(stats.packets_solved, 33);
            assert_eq!(stats.packet_max_variables, 4);
        }
    }
