    fn find(parent: &mut BTreeMap<usize, usize>, mut t: usize) -> usize {
        loop {
            let p = parent[&t];
            if p == t {
                return t;
            }
            let root = parent[&p];
            parent.insert(t, root);
            t = p;
        }
    }
    fn from_factor(f: &FactorModel) -> Result<Model, String> {
        let n = f.variables;
        let nt = f.tile_nodes.len() / 4;
        if n == 0
            || f.tile_nodes.len() % 4 != 0
            || f.tile_gauges.len() != f.tile_nodes.len()
            || f.bias.iter().any(|&h| h != 0)
            || (!f.physical_signs.is_empty()
                && (f.physical_signs.len() != f.mapping.len()
                    || f.physical_signs.iter().any(|&s| s != 1 && s != -1)))
        {
            return Err("junction requires zero physical bias and a valid signed lift".into());
        }
        let mut inc = vec![Vec::<usize>::new(); n];
        let mut regions = Vec::new();
        for t in 0..nt {
            let nodes = f.tile_nodes[4 * t..4 * t + 4]
                .iter()
                .map(|&u| usize::try_from(u).map_err(|_| "negative tile variable"))
                .collect::<Result<Vec<_>, _>>()?;
            if nodes.iter().any(|&u| u >= n)
                || nodes.iter().copied().collect::<BTreeSet<_>>().len() != 4
            {
                return Err("junction repeated tile variable".into());
            }
            for &u in &nodes {
                inc[u].push(t);
            }
            let gauges = &f.tile_gauges[4 * t..4 * t + 4];
            if gauges.iter().any(|&g| g != 1 && g != -1) {
                return Err("junction gauge".into());
            }
            let q2 = (0usize..16)
                .map(|mask| {
                    let q = (0..4)
                        .map(|u| gauges[u] * if mask >> u & 1 == 0 { -1 } else { 1 })
                        .sum::<i32>();
                    q * q
                })
                .collect();
            regions.push(Region {
                nodes,
                q2,
                fixed: vec![0; 16],
            });
        }
        let mut candidates = BTreeMap::<(usize, usize), Vec<usize>>::new();
        for (u, ts) in inc.iter().enumerate() {
            for a in 0..ts.len() {
                for b in a + 1..ts.len() {
                    candidates.entry((ts[a], ts[b])).or_default().push(u);
                }
            }
        }
        let mut candidates = candidates
            .into_iter()
            .filter(|(_, scope)| scope.len() >= 2)
            .collect::<Vec<_>>();
        candidates.sort_by_key(|(ab, scope)| (std::cmp::Reverse(scope.len()), *ab));
        let mut parents = inc
            .iter()
            .map(|ts| ts.iter().map(|&t| (t, t)).collect::<BTreeMap<_, _>>())
            .collect::<Vec<_>>();
        let mut links = Vec::new();
        for ((a, b), scope) in candidates {
            if scope.len() > 3 {
                continue;
            }
            if scope
                .iter()
                .all(|&u| find(&mut parents[u], a) == find(&mut parents[u], b))
            {
                continue;
            }
            for &u in &scope {
                let ra = find(&mut parents[u], a);
                let rb = find(&mut parents[u], b);
                parents[u].insert(rb, ra);
            }
            links.push(Link { a, b, scope });
        }
        let mut physical = vec![vec![0i32; 4]; nt];
        for (u, ts) in inc.iter().enumerate() {
            let mut representatives = BTreeMap::new();
            for &t in ts {
                representatives.entry(find(&mut parents[u], t)).or_insert(t);
            }
            for &t in representatives.values() {
                let pos = regions[t]
                    .nodes
                    .iter()
                    .position(|&v| v == u)
                    .ok_or("missing physical incidence")?;
                physical[t][pos] = 1;
            }
        }
        let edges = f
            .edge_u
            .iter()
            .zip(&f.edge_v)
            .zip(&f.edge_j)
            .map(|((&u, &v), &j)| {
                Ok::<_, String>((
                    usize::try_from(u).map_err(|_| "negative edge")?,
                    usize::try_from(v).map_err(|_| "negative edge")?,
                    j,
                ))
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Model {
            junction_links: links,
            physical_links: physical,
            n,
            fields: vec![0; n],
            constant: f.constant,
            regions,
            edges,
            region_colors: f.tile_offsets.clone(),
            edge_colors: f.edge_offsets.clone(),
            physical_mapping: f.mapping.clone(),
            physical_signs: f.physical_signs.clone(),
            physical_fixed: Vec::new(),
            edge_biases: Vec::new(),
        })
    }
    fn absorb_internal_pairs(model: &mut Model) -> Result<usize, String> {
        if !model.edge_biases.is_empty() {
            return Err("absorb before pair unary reparameterization".into());
        }
        let mut owner = BTreeMap::new();
        for (t, region) in model.regions.iter().enumerate() {
            for a in 0..region.nodes.len() {
                for b in a + 1..region.nodes.len() {
                    let (u, v) = (region.nodes[a], region.nodes[b]);
                    owner.entry((u.min(v), u.max(v))).or_insert((t, a, b));
                }
            }
        }
        let old = std::mem::take(&mut model.edges);
        let old_offsets = model.edge_colors.clone();
        let mut kept = Vec::new();
        let mut offsets = vec![0];
        let mut count = 0;
        for color in old_offsets.windows(2) {
            for &(u, v, j) in &old[color[0] as usize..color[1] as usize] {
                if let Some(&(t, a, b)) = owner.get(&(u.min(v), u.max(v))) {
                    for (mask, cost) in model.regions[t].fixed.iter_mut().enumerate() {
                        let product = if (mask >> a & 1) == (mask >> b & 1) {
                            1
                        } else {
                            -1
                        };
                        *cost = cost
                            .checked_add(j.checked_mul(product).ok_or("absorbed product overflow")?)
                            .ok_or("absorbed table overflow")?;
                    }
                    count += 1;
                } else {
                    kept.push((u, v, j));
                }
            }
            offsets.push(kept.len() as i32);
        }
        model.edges = kept;
        model.edge_colors = offsets;
        Ok(count)
    }
    #[derive(Clone,Debug,serde::Serialize)]
    struct WeakCliqueStats {
        complete_candidates:usize,cyclic_candidates:usize,frustrated_candidates:usize,selected_cliques:usize,selected_regions:usize,
        removed_pair_factors:usize,local_relaxation_gap_milli:i64,
        regions_before:usize,regions_after:usize,pairs_before:usize,pairs_after:usize,
        region_colors_before:usize,region_colors_after:usize,
        native_merges:usize,native_separator_links:usize,
    }
    // Replace induced weak K4/C4 pair terms by an exact 16-state potential.
    // Vertex-disjoint selections require only one appended region colour;
    // original native regions, junction indices and pair order are preserved.
    fn absorb_weak_cliques(model:&mut Model,join_native:bool)->Result<WeakCliqueStats,String>{absorb_weak_four_regions(model,join_native,false)}
    fn absorb_weak_four_regions(model:&mut Model,join_native:bool,include_squares:bool)->Result<WeakCliqueStats,String>{
        if !model.edge_biases.is_empty(){return Err("weak cliques require original pair unaries".into());}
        let n=model.n;let regions_before=model.regions.len();let pairs_before=model.edges.len();let colors_before=model.region_colors.len().checked_sub(1).ok_or("weak clique region colours")?;
        if n==0||n>5000||model.physical_links.len()!=regions_before||model.regions.iter().any(|r|r.nodes.len()!=4)||model.region_colors.first()!=Some(&0)||model.region_colors.last()!=Some(&(regions_before as i32))||model.region_colors.windows(2).any(|w|w[0]>w[1])||model.edge_colors.first()!=Some(&0)||model.edge_colors.last()!=Some(&(pairs_before as i32))||model.edge_colors.windows(2).any(|w|w[0]>w[1]){return Err("weak clique model/colour dimensions".into());}
        let mut weights=BTreeMap::<(usize,usize),(usize,i32)>::new();let mut adj=vec![BTreeSet::new();n];
        for(i,&(u,v,j))in model.edges.iter().enumerate(){if u>=n||v>=n||u==v{return Err("weak clique edge bounds".into());}if j==0||i64::from(j).abs()>=500{continue;}let(a,b)=(u.min(v),u.max(v));if weights.insert((a,b),(i,j)).is_some(){return Err("weak clique duplicate pair".into());}adj[a].insert(b);adj[b].insert(a);}
        struct Candidate{nodes:[usize;4],edges:Vec<usize>,table:Vec<i32>,gap:i64}
        let mut candidates=Vec::new();let mut complete=0;let mut sets=BTreeSet::<[usize;4]>::new();
        for a in 0..n{for &b in adj[a].range(a+1..){let common=adj[a].intersection(&adj[b]).copied().filter(|&v|v>b).collect::<Vec<_>>();
            for (ci,&c)in common.iter().enumerate(){for &d in &common[ci+1..]{if adj[c].contains(&d){sets.insert([a,b,c,d]);}}}
        }}
        if include_squares{
            // Two common neighbours of an endpoint pair form a simple C4.
            // Deduplicate scopes and include every induced weak chord exactly once.
            let mut common=BTreeMap::<(usize,usize),Vec<usize>>::new();
            for (v,neighbors)in adj.iter().enumerate(){let neighbors=neighbors.iter().copied().collect::<Vec<_>>();for(a,&u)in neighbors.iter().enumerate(){for &w in &neighbors[a+1..]{common.entry((u,w)).or_default().push(v);}}}
            for((u,w),middle)in common{for(a,&v)in middle.iter().enumerate(){for &z in &middle[a+1..]{let mut nodes=[u,w,v,z];nodes.sort_unstable();sets.insert(nodes);}}}
        }
        let cyclic=sets.len();
        for nodes in sets{
            let mut indices=Vec::new();let mut terms=Vec::new();
            for u in 0..4{for v in u+1..4{if let Some(&(index,j))=weights.get(&(nodes[u],nodes[v])){indices.push(index);terms.push((u,v,j));}}}
            if terms.len()==6{complete+=1;}
            let table=(0..16usize).map(|mask|terms.iter().map(|&(u,v,j)|if(mask>>u&1)==(mask>>v&1){j}else{-j}).sum::<i32>()).collect::<Vec<_>>();
            let gap=terms.iter().map(|&(_,_,j)|i64::from(j).abs()).sum::<i64>()+i64::from(*table.iter().min().ok_or("weak region empty table")?);
            if gap<0{return Err("weak region impossible local gap".into());}if gap>0{candidates.push(Candidate{nodes,edges:indices,table,gap});}
        }
        candidates.sort_by_key(|c|(std::cmp::Reverse(c.gap),c.nodes));let frustrated=candidates.len();let mut used=vec![false;n];let mut selected=Vec::new();
        for c in candidates{if c.nodes.iter().any(|&u|used[u]){continue;}for &u in &c.nodes{used[u]=true;}selected.push(c);}
        let mut plans=Vec::new();let mut native_merges=0;
        for c in selected{let anchor=if join_native{model.regions[..regions_before].iter().enumerate().filter(|(_,r)|r.q2.iter().any(|&q|q!=0)).filter_map(|(t,r)|{let scope=c.nodes.iter().copied().filter(|u|r.nodes.contains(u)).collect::<Vec<_>>();(scope.len()>=2).then_some((t,scope))}).max_by_key(|(t,s)|(s.len(),std::cmp::Reverse(*t)))}else{None};if anchor.as_ref().is_some_and(|(_,scope)|scope.len()==4){native_merges+=1;}plans.push((c,anchor));}
        let selected_count=plans.len();let selected_cliques=plans.iter().filter(|(c,_)|c.edges.len()==6).count();let appended=selected_count-native_merges;
        if appended>0&&colors_before>=32{return Err("weak cliques exceed the CUDA 32 region colour limit".into());}
        let mut removed=vec![false;pairs_before];let mut local_gap=0;let mut native_links=0;
        for(c,anchor)in plans{for i in c.edges{if std::mem::replace(&mut removed[i],true){return Err("weak clique pair selected twice".into());}}local_gap+=c.gap;
            if let Some((t,scope))=&anchor{if scope.len()==4{let native=&mut model.regions[*t];for mask in 0..16{let mut mapped=0;for(k,u)in c.nodes.iter().enumerate(){let p=native.nodes.iter().position(|v|v==u).ok_or("weak/native merge scope")?;mapped|=(mask>>p&1)<<k;}native.fixed[mask]=native.fixed[mask].checked_add(c.table[mapped]).ok_or("weak/native table overflow")?;}continue;}}
            let new=model.regions.len();let mut physical=vec![1;4];if let Some((t,scope))=anchor{for u in &scope{let at=c.nodes.iter().position(|v|v==u).ok_or("weak/native separator scope")?;physical[at]=0;}model.junction_links.push(Link{a:t,b:new,scope});native_links+=1;}
            model.regions.push(Region{nodes:c.nodes.to_vec(),q2:vec![0;16],fixed:c.table});model.physical_links.push(physical);
        }
        if selected_count>0{let mut edges=Vec::with_capacity(pairs_before-removed.iter().filter(|&&v|v).count());let mut offsets=vec![0];for range in model.edge_colors.windows(2){for i in range[0]as usize..range[1]as usize{if !removed[i]{edges.push(model.edges[i]);}}offsets.push(edges.len()as i32);}model.edges=edges;model.edge_colors=offsets;if appended>0{model.region_colors.push(model.regions.len()as i32);}}
        Ok(WeakCliqueStats{complete_candidates:complete,cyclic_candidates:cyclic,frustrated_candidates:frustrated,selected_cliques,selected_regions:selected_count,removed_pair_factors:removed.iter().filter(|&&v|v).count(),local_relaxation_gap_milli:local_gap,regions_before,regions_after:model.regions.len(),pairs_before,pairs_after:model.edges.len(),region_colors_before:colors_before,region_colors_after:model.region_colors.len()-1,native_merges,native_separator_links:native_links})
    }
    // Transport only inside the same singleton/joint message representation.
    // Replace at most a quarter of each class and retain every elite trajectory.
    fn replica_transport_map(energies:&[i64],states:&[Vec<i8>],minsum:usize,gauge:bool,round:usize)->Result<Vec<usize>,String>{
        let n=energies.len();if n==0||states.len()!=n||minsum>n||states[0].is_empty()||states.iter().any(|s|s.len()!=states[0].len()||s.iter().any(|&v|v!=1&&v!=-1)){return Err("replica transport population dimensions/spins".into());}
        let mut map=(0..n).collect::<Vec<_>>();
        for range in [0..minsum,minsum..n]{
            let mut ranked=range.collect::<Vec<_>>();ranked.sort_by_key(|&r|(energies[r],r));let quota=ranked.len()/4;if quota==0{continue;}
            let mut seen=BTreeSet::new();let mut elite=Vec::new();for &r in &ranked{let sign=if gauge{states[r][0]}else{1};if seen.insert(states[r].iter().map(|&s|s*sign).collect::<Vec<_>>()){elite.push(r);}if elite.len()==quota{break;}}
            for (k,&dst)in ranked.iter().rev().filter(|r|!elite.contains(r)).take(quota).enumerate(){
                for shift in 0..elite.len(){let src=elite[(round+k+shift)%elite.len()];if energies[src]<energies[dst]&&(src%7,src%6)!=(dst%7,dst%6){map[dst]=src;break;}}
            }
        }
        Ok(map)
    }
    fn remap_replica_buffer(values:&[f32],map:&[usize])->Result<Vec<f32>,String>{
        if map.is_empty()||values.len()%map.len()!=0||map.iter().any(|&r|r>=map.len())||values.iter().any(|v|!v.is_finite()){return Err("replica transport buffer dimensions/nonfinite".into());}
        let stride=values.len()/map.len();let mut out=Vec::with_capacity(values.len());for &r in map{out.extend_from_slice(&values[r*stride..(r+1)*stride]);}Ok(out)
    }
    // Differential evolution in the affine message-state representation:
    // coefficients 1,+1/2,-1/2 keep each physical field counted once.
    fn differential_transport_plan(map:&[usize],minsum:usize,round:usize)->Result<Vec<[usize;3]>,String>{
        if map.is_empty()||minsum>map.len()||map.iter().enumerate().any(|(r,&src)|src>=map.len()||(r<minsum)!=(src<minsum)){return Err("differential transport class dimensions".into());}
        let mut plan=Vec::new();for(r,&src)in map.iter().enumerate(){if src==r{plan.push([r,r,r]);continue;}let(lo,hi)=if r<minsum{(0,minsum)}else{(minsum,map.len())};let width=hi-lo;if width<4{return Err("differential transport needs four class members".into());}
            let mut a=lo+(r.wrapping_mul(17).wrapping_add(round.wrapping_mul(13)))%width;while a==r||a==src{a=lo+(a-lo+1)%width;}
            let mut b=lo+(r.wrapping_mul(31).wrapping_add(round.wrapping_mul(7)).wrapping_add(3))%width;while b==r||b==src||b==a{b=lo+(b-lo+1)%width;}plan.push([src,a,b]);
        }Ok(plan)
    }
    fn differential_transport_buffer(values:&[f32],plan:&[[usize;3]])->Result<Vec<f32>,String>{
        if plan.is_empty()||values.len()%plan.len()!=0||plan.iter().flatten().any(|&r|r>=plan.len())||values.iter().any(|v|!v.is_finite()){return Err("differential buffer dimensions/nonfinite".into());}
        let stride=values.len()/plan.len();let mut out=Vec::with_capacity(values.len());for(r,&[src,a,b])in plan.iter().enumerate(){if src==r&&a==r&&b==r{out.extend_from_slice(&values[r*stride..(r+1)*stride]);}else{for u in 0..stride{out.push(values[src*stride+u]+0.5*(values[a*stride+u]-values[b*stride+u]));}}}if out.iter().any(|v|!v.is_finite()){return Err("differential output nonfinite".into());}Ok(out)
    }
    #[cfg(test)]mod replica_transport_tests{
        use super::*;
        #[test]fn transport_keeps_elites_semantics_determinism_and_quarter_limit(){
            let e=(0..48).map(|r|r as i64).collect::<Vec<_>>();let states=(0..48).map(|r|(0..8).map(|u|if r>>u&1==0{-1}else{1}).collect::<Vec<_>>()).collect::<Vec<_>>();let map=replica_transport_map(&e,&states,16,true,1).unwrap();assert_eq!(map,replica_transport_map(&e,&states,16,true,1).unwrap());assert_eq!(map[0],0);assert_eq!(map[16],16);for range in [0..16,16..48]{assert!(range.clone().filter(|&r|map[r]!=r).count()<=range.len()/4);assert!(range.clone().any(|r|map[r]!=r));for r in range{let src=map[r];assert_eq!(src<16,r<16);if src!=r{assert!(e[src]<e[r]);assert_ne!((src%7,src%6),(r%7,r%6));assert_eq!(map[src],src);}}}
        }
        #[test]fn differential_plan_preserves_message_classes_and_distinct_peers(){
            let mut map=(0..16).collect::<Vec<_>>();map[7]=0;map[15]=8;let plan=differential_transport_plan(&map,8,1).unwrap();assert_eq!(plan,differential_transport_plan(&map,8,1).unwrap());for r in 0..16{let[src,a,b]=plan[r];assert_eq!(src,map[r]);assert_eq!(src<8,r<8);assert_eq!(a<8,r<8);assert_eq!(b<8,r<8);if map[r]!=r{assert!(a!=src&&b!=src&&a!=b&&a!=r&&b!=r);}else{assert_eq!(plan[r],[r,r,r]);}}
            assert!(differential_transport_plan(&[0,0,1],1,0).is_err());assert!(differential_transport_plan(&[0,1],3,0).is_err());assert!(differential_transport_plan(&[2,1],1,0).is_err());
        }
        #[test]fn differential_messages_preserve_affine_cavity_accounting_and_unchanged_bits(){
            let plan=vec![[0,0,0],[0,2,3],[2,2,2],[3,3,3]];let field=[3.,-5.];let b=vec![1.,2.,-3.,4.,5.,-6.,7.,8.];let em=vec![2.,3.,4.,5.,6.,7.,8.,9.];let rm=vec![9.,8.,7.,6.,5.,4.,3.,2.];let jm=vec![-1.,-2.,-3.,-4.,-5.,-6.,-7.,-8.];let h=(0..8).map(|u|field[u%2]+b[u]+em[u]+rm[u]+jm[u]).collect::<Vec<_>>();let hb=differential_transport_buffer(&h,&plan).unwrap();let bb=differential_transport_buffer(&b,&plan).unwrap();let eb=differential_transport_buffer(&em,&plan).unwrap();let rb=differential_transport_buffer(&rm,&plan).unwrap();let jb=differential_transport_buffer(&jm,&plan).unwrap();for u in 0..8{assert_eq!(hb[u],field[u%2]+bb[u]+eb[u]+rb[u]+jb[u]);if u/2!=1{assert_eq!(hb[u].to_bits(),h[u].to_bits());}}assert!(differential_transport_buffer(&[f32::MAX,-f32::MAX,0.,0.],&[[0,0,1];4]).is_err());assert!(differential_transport_buffer(&[f32::NAN],&[[0,0,0]]).is_err());
        }
        #[test]fn snapshot_transport_handles_cycles_duplicates_zero_stride_and_rejects_invalid_inputs(){
            assert_eq!(remap_replica_buffer(&[1.,2.,3.,4.,5.,6.],&[1,2,0]).unwrap(),vec![3.,4.,5.,6.,1.,2.]);assert_eq!(remap_replica_buffer(&[1.,2.,3.,4.],&[0,0]).unwrap(),vec![1.,2.,1.,2.]);assert!(remap_replica_buffer(&[],&[1,0]).unwrap().is_empty());assert!(remap_replica_buffer(&[1.],&[0,0]).is_err());assert!(remap_replica_buffer(&[1.,f32::NAN],&[0,1]).is_err());assert!(remap_replica_buffer(&[1.,2.],&[2,0]).is_err());assert!(remap_replica_buffer(&[],&[]).is_err());
            assert!(replica_transport_map(&[0],&[vec![0]],0,true,0).is_err());assert!(replica_transport_map(&[0],&[vec![1]],2,true,0).is_err());let states=vec![vec![1,-1];8];assert_eq!(replica_transport_map(&[0;8],&states,4,true,0).unwrap(),(0..8).collect::<Vec<_>>());
        }
    }
