                    largest=largest.max(size);if charges(tiles,&s)!=expected{return Err("regular cover cycle changed a tile charge".into());}if let Some(refine)=refine{s=refine(&s)?;if charges(tiles,&s)!=expected{return Err("physical circulation readout changed native charge".into());}}let energy=objective.score(&s);best=best.min(energy);if (diverse||energy<=base+4000)&&states.insert(s.clone()){reads.push((s,energy));}
                    if diverse{let support=origin.iter().filter_map(|&i|(arcs[i].var!=usize::MAX).then_some(arcs[i].var)).collect::<BTreeSet<_>>();let mut next=banned.clone();next.extend(arcs.iter().enumerate().filter_map(|(i,a)|support.contains(&a.var).then_some(i)));next.sort_unstable();next.dedup();if queue.len()<4096&&queued.insert(next.clone()){queue.push_front(next);}}
