                let physical=Graph{h_milli:vec![0;6],edges:vec![(0,1),(1,3),(2,4)],j_milli:vec![45,-45,45],offset_milli:0,nonce_bytes:vec![],instance_digest_bytes:vec![]};let objective=RoundGraph::new(&physical,6,&[0,1,2,3,4,5],&[],&[]).unwrap();let mut checked=0usize;
                fn walk(start:usize,u:usize,arcs:&[Arc],adj:&[Vec<usize>],seen:&mut[bool],path:&mut Vec<usize>,tiles:&[Vec<(usize,i32)>],parent:&[i8],checked:&mut usize){
                    for &i in &adj[u]{let v=arcs[i].to;if v==start{path.push(i);if repeated_cover_variable(arcs,path).is_none(){let mut child=parent.to_vec();for &e in path.iter(){if arcs[e].var!=usize::MAX{child[arcs[e].var]=-child[arcs[e].var];}}assert_eq!(charges(tiles,&child),charges(tiles,parent));if path.iter().any(|&e|arcs[e].var!=usize::MAX){*checked+=1;}}path.pop();}else if v>start&&!seen[v]{seen[v]=true;path.push(i);walk(start,v,arcs,adj,seen,path,tiles,parent,checked);path.pop();seen[v]=false;}}
                }
