            #[test]fn extremal_preserves_record_after_uphill_steps_and_handles_zero_work(){let g=RoundGraph{fields:vec![0;3],edges:vec![(0,1,-5),(0,2,-5),(1,2,-5)],adj:vec![vec![(1,-5),(2,-5)],vec![(0,-5),(2,-5)],vec![(0,-5),(1,-5)]],constant:0};let parent=[1,1,-1];let(reads,stats)=trial(&g,&parent,256,1000,1,false,None,&||false).unwrap();assert_eq!(stats["best_milli"],-15);assert!(reads.iter().any(|(_,e)|*e==-15));assert!(stats["uphill_moves"].as_u64().unwrap()>0);let(reads,stats)=trial(&g,&parent,0,1000,0,false,None,&||false).unwrap();assert!(reads.iter().all(|(_,e)|*e==5));assert_eq!(stats["steps"],0);}
