    // explicit so defects can move within the chosen native-connected region.
    pub fn conditional_patch_seed_batch(engine:&NativeSeed,instance:&Instance,batch:&mut SeedBatch,stopped:&dyn Fn()->bool)->Result<(),String>{
        let wall=std::time::Instant::now();let parent=batch.reads.iter().min_by_key(|r|r.energy_milli).ok_or("empty conditional parent")?.clone();let protected=batch.reads.len();
        let prepared=PreparedGraph::from_instance(instance,&TWISTED_DIMER_V1,Weights::FULL,&crate::cluster::sampler::HEADLESS_LIMITS,1).map_err(|e|e.to_string())?;let original=|u:i32|prepared.device_to_original()[u as usize];let pairs=prepared.layout().pairs.chunks_exact(2).map(|p|(original(p[0]),original(p[1]))).collect::<Vec<_>>();
        let mut f=FactorModel::from_instance_releasing(instance,&crate::cluster::sampler::HEADLESS_LIMITS,&parent.spins,&pairs)?;f.bias.fill(0);
        let mut logical=vec![0i8;f.variables];for(u,&v)in f.mapping.iter().enumerate(){let sign=parent.spins[u]*f.physical_signs.get(u).copied().unwrap_or(1);if logical[v]!=0&&logical[v]!=sign{return Err("conditional parent mapping conflict".into());}logical[v]=sign;}
        if f.lift_spins(&logical)?!=parent.spins{return Err("conditional parent lift mismatch".into());}
        let mut job=engine.kernel.prepare(&f,instance,crate::search_config().replicas)?;let n=job.model.n;let replicas=job.replicas;
        let mut adj=vec![Vec::new();n];for region in &job.model.regions{for &u in &region.nodes{for &v in &region.nodes{if u!=v{adj[u].push(v);}}}}for &(u,v,j)in &job.model.edges{if j.abs()>=1000&&u!=v{adj[u].push(v);adj[v].push(u);}}for row in &mut adj{row.sort_unstable();row.dedup();}
        let mut delta=vec![0i64;n];for (u,&h)in instance.h().iter().enumerate(){delta[f.mapping[u]]-=2*i64::from(h)*i64::from(parent.spins[u]);}for(&(u,v),&j)in instance.edges().iter().zip(instance.j()){let(u,v)=(u as usize,v as usize);let(a,b)=(f.mapping[u],f.mapping[v]);if a!=b{let d=-2*i64::from(j)*i64::from(parent.spins[u])*i64::from(parent.spins[v]);delta[a]+=d;delta[b]+=d;}}
        let mut ranked=(0..n).collect::<Vec<_>>();ranked.sort_by_key(|&u|(delta[u],u));let mut masks=Vec::with_capacity(n*replicas);let mut biases=Vec::with_capacity(n*replicas);let mut sizes=Vec::new();
        for r in 0..replicas{let mut confidence=delta.iter().map(|&d|d.max(0)as f32+1.).collect::<Vec<_>>();confidence[ranked[r%ranked.len().min(64)]]=0.;let denominator=1usize<<(1+(r/7)%4);let mask=confidence_patch(&adj,&confidence,r,(n/denominator).max(1))?;sizes.push(mask.iter().filter(|&&v|v!=0).count());biases.extend((0..n).map(|u|-i32::from(logical[u])*if mask[u]==0{65536}else{1}));masks.extend(mask);}
        job.seed_conditional(&biases,&masks)?;job.begin_batch(1000)?;
        let mut trace=Vec::new();for cursor in (0..1500).step_by(100){if stopped(){return Err("conditional search cancelled".into());}job.advance(cursor,100)?;trace.push(job.best_read()?.energy_milli);}
        let reads=job.finish_batch()?;let raw=reads.iter().map(|r|r.energy_milli).min();for(r,read)in reads.iter().enumerate(){for(u,&v)in f.mapping.iter().enumerate(){if masks[r*n+v]==0&&read.spins[u]!=parent.spins[u]{return Err("conditional boundary changed".into());}}}
        batch.reads.extend(reads);close_seed_batch(instance,batch,stopped)?;let after=batch.reads.iter().map(|r|r.energy_milli).min().ok_or("empty conditional result")?;if after>parent.energy_milli{return Err("conditional search lost incumbent".into());}
        batch.stats["conditional_lns"]=serde_json::json!({"before_milli":parent.energy_milli,"after_milli":after,"gain_milli":parent.energy_milli-after,"raw_best_milli":raw,"protected_prefix_reads":protected,"new_reads":replicas,"updates":1500,"logical_variables":n,"released_dimers":pairs.len(),"free_variables_per_replica":sizes,"boundary_verified":true,"original_H_verified":true,"energy_trace_milli":trace,"seconds_including_closure":wall.elapsed().as_secs_f64()});Ok(())
    }
    #[doc = " Let defects change their dimer/charge trade-off; all other dimers retain"]
    #[doc = " their satisfied contraction. Every broken pair is released, so the parent"]
    #[doc = " remains exactly representable without a signed hard-sector restriction."]
    fn defect_neighborhood_pairs(h:&[i32],edges:&[(usize,usize,i32)],tiles:&[[usize;4]],pairs:&[(usize,usize)],base:&[(usize,usize)])->Result<(Vec<(usize,usize)>,serde_json::Value),String>{
        let n=h.len();if edges.iter().any(|&(u,v,_)|u>=n||v>=n)||tiles.iter().flatten().any(|&u|u>=n)||pairs.iter().any(|&(u,v)|u>=n||v>=n||u==v)||base.iter().any(|&(u,v)|u>=n||v>=n||u==v){return Err("defect neighborhood dimensions".into());}
        let mut mate=vec![usize::MAX;n];for &(u,v)in pairs{if mate[u]!=usize::MAX||mate[v]!=usize::MAX{return Err("defect neighborhood non-disjoint dimers".into());}mate[u]=v;mate[v]=u;}
        if base.iter().any(|&(u,v)|mate[u]!=v){return Err("defect neighborhood base is not a native dimer".into());}
        let mut external=h.iter().map(|&v|i64::from(v).abs()).collect::<Vec<_>>();for &(u,v,j)in edges{if u!=v&&mate[u]!=v{external[u]+=i64::from(j).abs();external[v]+=i64::from(j).abs();}}
        let mut seed=vec![false;n];for &(u,v)in base{seed[u]=true;seed[v]=true;}let mut neighborhood=seed.clone();let mut touched_tiles=0usize;for tile in tiles{if tile.iter().any(|&u|seed[u]){touched_tiles+=1;for &u in tile{neighborhood[u]=true;}}}
        let mut released=base.iter().map(|&(u,v)|(u.min(v),u.max(v))).collect::<BTreeSet<_>>();let old=released.len();let mut dominance_retained=0usize;let mut neighbor_candidates=0usize;
        for &(u,v)in pairs{let pair=(u.min(v),u.max(v));if released.contains(&pair)||!neighborhood[u]&&!neighborhood[v]{continue;}neighbor_candidates+=1;
            // If one endpoint's entire external field L1 is strictly below J,
            // aligning a broken ferromagnetic pair strictly lowers original H.
            if external[u]<1000||external[v]<1000{dominance_retained+=1;continue;}released.insert(pair);
        }
        let total=released.len();Ok((released.into_iter().collect(),serde_json::json!({"base_released":old,"new_neighbor_releases":total-old,"touched_native_tiles":touched_tiles,"neighbor_candidates":neighbor_candidates,"dominant_neighbor_dimers_retained":dominance_retained,"strict_external_L1_dominance_bound_milli":1000,"native_check_hops":1})))
    }
    fn defect_release_pairs(
        instance: &Instance,
        parent: &[i8],
    ) -> Result<Vec<(usize, usize)>, String> {
        if parent.len() != instance.h().len() || parent.iter().any(|&s| s != 1 && s != -1) {
            return Err("defect seed shape".into());
        }
        let prepared = PreparedGraph::from_instance(
            instance,
            &TWISTED_DIMER_V1,
            Weights::FULL,
            &crate::cluster::sampler::HEADLESS_LIMITS,
            1,
        )
        .map_err(|e| e.to_string())?;
        let layout = prepared.layout();
        let original = |u: i32| prepared.device_to_original()[u as usize];
        let mut charged = BTreeSet::new();
        for (tile, gauges) in layout
            .tiles
            .chunks_exact(4)
            .zip(layout.gauges.chunks_exact(4))
        {
            if tile
                .iter()
                .zip(gauges)
                .map(|(&u, &g)| i32::from(parent[original(u)]) * i32::from(g))
                .sum::<i32>()
                != 0
            {
                charged.extend(tile.iter().map(|&u| original(u)));
            }
        }
        let mut released = Vec::new();
        for pair in layout.pairs.chunks_exact(2) {
            let (u, v) = (original(pair[0]), original(pair[1]));
            if parent[u] != parent[v] || charged.contains(&u) || charged.contains(&v) {
                released.push((u.min(v), u.max(v)));
            }
        }
        released.sort_unstable();
        released.dedup();
        Ok(released)
    }
    #[doc = " Native q^2/4 counts exact2000milli excitation units. Keeping the lowest H"]
    #[doc = " at each exact strong cost also keeps the lowest weak cost in that stratum."]
    fn record_strong_quanta(regions: &[Region], raw: &[i8]) -> Result<usize, String> {
        let mut total = 0i64;
        for region in regions {
            let mask = region
                .nodes
                .iter()
                .enumerate()
                .try_fold(0usize, |m, (p, &u)| {
                    raw.get(u)
                        .map(|&s| m | (usize::from(s > 0) << p))
                        .ok_or("strong archive endpoint")
                })?;
            let q = *region.q2.get(mask).ok_or("strong archive table shape")?;
            if q < 0 || q % 4 != 0 {
                return Err("strong archive requires native excitation quanta".into());
            }
            total += i64::from(q) / 4;
        }
        usize::try_from(total).map_err(|_| "strong excitation count overflow".into())
    }
    pub fn release_seed_batch(
        engine: &NativeSeed,
        instance: &Instance,
        batch: &mut SeedBatch,
        stopped: &dyn Fn() -> bool,
    ) -> Result<(), String> {
        shared_unpin_seed_batch(engine, instance, batch, stopped)
    }

