fn ordered_worker_ranges(jobs:usize,workers:usize)->Vec<std::ops::Range<usize>>{let count=jobs.min(workers.max(1));if count==0{return Vec::new();}let base=jobs/count;let extra=jobs%count;let mut at=0;(0..count).map(|i|{let start=at;at+=base+usize::from(i<extra);start..at}).collect()}
