// Early-abort screen (opt-in; both settings None = disabled = unchanged behaviour).
// Decision is made on the best cold-search energy of the job only. Returns Some(reason) to abort the rest of the solve.
// A fixed cutoff takes precedence; otherwise a rolling quantile of the last `window` cold energies is used
// (everything continues until `warmup` salts have been seen).
static SCREEN_WINDOW:std::sync::Mutex<std::collections::VecDeque<i64>>=std::sync::Mutex::new(std::collections::VecDeque::new());
fn screen_decide(cutoff:Option<i64>,keep:Option<f64>,warmup:usize,cap:usize,window:&mut std::collections::VecDeque<i64>,energy:i64)->Option<String>{
    if cutoff.is_none()&&keep.is_none(){return None;}
    let verdict=if let Some(cutoff)=cutoff{
        if energy>cutoff{Some(format!("cold best {energy} above cutoff {cutoff}"))}else{None}
    }else{
        let q=keep.unwrap_or(1.);
        if window.len()<warmup||window.is_empty(){None}else{
            let mut v:Vec<i64>=window.iter().copied().collect();v.sort_unstable();
            let at=(((v.len() as f64)*q).ceil() as usize).saturating_sub(1).min(v.len()-1);let limit=v[at];
            if energy>limit{Some(format!("cold best {energy} above rolling {q} quantile {limit} of {} salts",v.len()))}else{None}
        }
    };
    window.push_back(energy);while window.len()>cap{window.pop_front();}
    verdict
}
thread_local!{static SCREEN_BYPASS:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}
struct ScreenBypassScope(bool);impl ScreenBypassScope{fn new()->Self{Self(SCREEN_BYPASS.with(|v|v.replace(true)))}}impl Drop for ScreenBypassScope{fn drop(&mut self){SCREEN_BYPASS.with(|v|v.set(self.0));}}
// Re-roll rule: a salt that survived the screen but did not reach the target, and is close to it, is searched again with
// different trajectory seeds (the energy noise between seeds is about 1 unit; the instance itself is unchanged).
fn erfc_approx(x:f64)->f64{let t=1.0/(1.0+0.3275911*x.abs());let y=t*(0.254829592+t*(-0.284496736+t*(1.421413741+t*(-1.453152027+t*1.061405429))))*(-x*x).exp();if x>=0.0{y}else{2.0-y}}
fn reroll_wanted(first_best_milli:i64,target_milli:i64,within_milli:i64,screened_out:bool,seeds:usize)->bool{
    seeds>0&&!screened_out&&first_best_milli>target_milli&&first_best_milli<=target_milli.saturating_add(within_milli)
}
fn screen_gate(cold_best_milli:i64)->Option<String>{
    if SCREEN_BYPASS.with(|v|v.get()){return None;}
    let cfg=search_config();
    let mut window=SCREEN_WINDOW.lock().unwrap_or_else(|e|e.into_inner());
    screen_decide(cfg.screen_cold_cutoff_milli,cfg.screen_keep_fraction,cfg.screen_warmup,cfg.screen_window,&mut window,cold_best_milli)
}
#[cfg(test)]mod screen_gate_tests{
    use super::*;use std::collections::VecDeque;
    #[test]fn reroll_only_for_unscreened_near_misses(){
        assert!(!reroll_wanted(-5088000,-5090000,2500,false,0));assert!(reroll_wanted(-5088000,-5090000,2500,false,4));
        assert!(!reroll_wanted(-5090000,-5090000,2500,false,4),"already at target");assert!(!reroll_wanted(-5091000,-5090000,2500,false,4),"better than target");
        assert!(reroll_wanted(-5087500,-5090000,2500,false,4));assert!(!reroll_wanted(-5087499,-5090000,2500,false,4),"too far");assert!(!reroll_wanted(-5088000,-5090000,2500,true,4),"screened out");}
    #[test]fn disabled_gate_never_aborts_and_keeps_no_state(){let mut w=VecDeque::new();assert!(screen_decide(None,None,30,200,&mut w,-1).is_none());assert!(w.is_empty());}
    #[test]fn fixed_cutoff_aborts_only_above_the_cutoff(){let mut w=VecDeque::new();assert!(screen_decide(Some(-5000),None,30,200,&mut w,-5000).is_none());assert!(screen_decide(Some(-5000),None,30,200,&mut w,-4999).is_some());assert!(screen_decide(Some(-5000),None,30,200,&mut w,-5100).is_none());}
    #[test]fn rolling_quantile_continues_during_warmup_then_keeps_the_best_fraction(){
        let mut w=VecDeque::new();for e in 0..30{assert!(screen_decide(None,Some(0.1),30,200,&mut w,-1000-e).is_none(),"warmup must continue");}
        // window holds -1000..-1029 ; the best 10% limit is the 3rd best = -1027
        assert!(screen_decide(None,Some(0.1),30,200,&mut w,-1027).is_none());assert!(screen_decide(None,Some(0.1),30,200,&mut w,-1010).is_some());assert!(screen_decide(None,Some(0.1),30,200,&mut w,-1100).is_none());}
    #[test]fn window_is_bounded(){let mut w=VecDeque::new();for e in 0..500{let _=screen_decide(None,Some(0.5),10,50,&mut w,-e);}assert_eq!(w.len(),50);}
}
