fn default_refinement_method(explicit:Option<&str>)->&str{explicit.unwrap_or("vector-axis")}
fn configure_profile() {
    // Startup only, before worker/governor threads exist. Explicit research
    // overrides remain available; the verified node default adds vector-axis.
    if std::env::var_os("QUIP_TWO_PASS_REFINEMENT").is_none(){std::env::set_var("QUIP_TWO_PASS_REFINEMENT",default_refinement_method(None));}
    for (k, _) in std::env::vars() {
        if k.starts_with("QUIP_NATIVE_SEED_") || k.starts_with("QUIP_HYBRID_") {
            std::env::remove_var(k);
        }
    }
    for flag in PROFILE_FLAGS {
        std::env::set_var(format!("QUIP_NATIVE_SEED_{flag}"), "1");
    }
    if !search_config().pair_refinement{std::env::remove_var("QUIP_NATIVE_SEED_PAIR_GAIN");}
    if !search_config().pair_triples{std::env::remove_var("QUIP_NATIVE_SEED_PAIR_TRIPLES");}
    match search_config().archive_policy.as_str(){"off"=>{std::env::remove_var("QUIP_NATIVE_SEED_RECORD_ARCHIVE");},"charge"=>{std::env::set_var("QUIP_NATIVE_SEED_CHARGE_ARCHIVE","1");},"strong"=>{std::env::set_var("QUIP_NATIVE_SEED_STRONG_COST_ARCHIVE","1");},_=>{}}
}
