    #[test]fn native_followup_policy_preserves_first_pass_and_restores_scopes(){
        let c=search_config_from_patch(serde_json::json!({"native_cluster_passes":2,"native_cluster_followup_selection":"strong-joint"})).unwrap();
        assert_eq!(c.native_cluster_selection,"weak");assert_eq!(c.native_cluster_followup_selection.as_deref(),Some("strong-joint"));assert_eq!(c.second.updates,3500);
        assert!(search_config_from_patch(serde_json::json!({"native_cluster_followup_selection":"strong-joint"})).is_err());assert!(search_config_from_patch(serde_json::json!({"native_cluster_passes":2,"native_cluster_followup_selection":"bad"})).is_err());
        assert_eq!(effective_native_cluster_selection(),"weak");{let _a=NativeClusterSelectionScope::new(Some("strong-joint".into()));assert_eq!(effective_native_cluster_selection(),"strong-joint");{let _b=NativeClusterSelectionScope::new(Some("frustration".into()));assert_eq!(effective_native_cluster_selection(),"frustration");}assert_eq!(effective_native_cluster_selection(),"strong-joint");}assert_eq!(effective_native_cluster_selection(),"weak");
    }
    #[test]fn native_cluster_budget_scope_preserves_archives_and_restores_nested_state(){
        assert_eq!(seeded_update_budget(3500,3000,None),(3500,3000));
        {let _scope=SeededUpdateScope::new(Some(5000));assert_eq!(seeded_update_budget(3500,3000,None),(5000,3000));
         {let _nested=SeededUpdateScope::new(Some(2000));assert_eq!(seeded_update_budget(3500,3000,None),(2000,0));}
         assert_eq!(seeded_update_budget(3500,3000,None),(5000,3000));assert_eq!(seeded_update_budget(3500,3000,Some(1000)),(1000,0));}
        assert_eq!(seeded_update_budget(3500,3000,None),(3500,3000));
    }
    #[test]fn cscreen_probe_scope_restores_budget_and_rejects_partial_chunks(){assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),None);{let _scope=CscreenProbeScope::new(2000).unwrap();assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),Some(2000));{let _nested=CscreenProbeScope::new(3500).unwrap();assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),Some(3500));}assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),Some(2000));for invalid in [0,99,750,100500]{assert!(CscreenProbeScope::new(invalid).is_err());assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),Some(2000));}}assert_eq!(CSCREEN_PROBE_UPDATES.with(|v|v.get()),None);}
    #[test]fn trajectory_and_native_limit_scopes_restore_nested_state(){
        assert_eq!(trajectory_seed(1000),1000);{let _s=TrajectoryScope::new(1);assert_eq!(trajectory_seed(1000),1001);assert_eq!(trajectory_seed(u64::MAX),0);{let _s=TrajectoryScope::new(7);assert_eq!(trajectory_seed(1000),1007);}assert_eq!(trajectory_seed(1000),1001);}assert_eq!(trajectory_seed(1000),1000);
        let original=native_refinement_limit();{let _s=NativeLimitScope::new(0);assert_eq!(native_refinement_limit(),0);{let _s=NativeLimitScope::new(7);assert_eq!(native_refinement_limit(),7);}assert_eq!(native_refinement_limit(),0);}assert_eq!(native_refinement_limit(),original);
    }
    #[test]
    fn partial_overrides_keep_fast_stage_defaults_and_reject_unknown_fields(){
        let c=search_config_from_patch(serde_json::json!({"second":{"seed":2000}})).unwrap();assert_eq!(c.second.seed,2000);assert_eq!(c.second.updates,3500);assert_eq!(c.second.refinement_pass_limit,1);assert_eq!(c.cold.updates,6000);assert_eq!(c.first.updates,3500);assert!(search_config_from_patch(serde_json::json!({"second":{"typo":3}})).is_err());assert!(search_config_from_patch(serde_json::json!({"typo":3})).is_err());
    }
    #[test]
    fn configuration_rejects_invalid_work_and_unknown_fields() {
        assert!(serde_json::from_str::<SearchConfig>(r#"{"typo":8}"#).is_err());
        for v in [0,1,99,101,100001]{let mut c=SearchConfig::default();c.first.updates=v;assert!(c.validate().is_err());}
        for v in [65,usize::MAX]{let mut c=SearchConfig::default();c.cpu_workers=v;assert!(c.validate().is_err());}
        let mut c=SearchConfig::default();c.second.snapshot=6000;assert!(c.validate().is_err());
        c.second.snapshot=0;c.cpu_workers=24;c.validate().unwrap();
        c.minsum_replicas=Some(c.replicas+1);assert!(c.validate().is_err());
        c.minsum_replicas=None;c.damping_base=f32::NAN;assert!(c.validate().is_err());
        c.damping_base=0.9;assert!(c.validate().is_err());
        c.damping_base=0.1;c.penalty_step=-1.;assert!(c.validate().is_err());
    }
    #[test]
    fn ordered_worker_ranges_cover_each_donor_once_and_balance_work() {
        for jobs in 0..129{for workers in [1,2,4,6,8,12,16,24,32,64,256]{let ranges=ordered_worker_ranges(jobs,workers);assert_eq!(ranges.len(),jobs.min(workers));assert_eq!(ranges.iter().flat_map(|r|r.clone()).collect::<Vec<_>>(),(0..jobs).collect::<Vec<_>>());if !ranges.is_empty(){let sizes=ranges.iter().map(|r|r.len()).collect::<Vec<_>>();assert!(sizes.iter().max().unwrap()-sizes.iter().min().unwrap()<=1);assert!(!sizes.contains(&0));}}}
    }
    #[test]
    fn cuda_float_literals_round_trip_configuration_values() {
        for value in [f32::MIN_POSITIVE,1e-20,1e-10,0.05,0.1,0.15,75.,100.,125.,150.,175.,225.,250.,275.,375.,9999.]{let literal=cuda_float_literal(value);let parsed=literal.strip_suffix('f').unwrap().parse::<f32>().unwrap();assert_eq!(parsed.to_bits(),value.to_bits());}
        let mut c=SearchConfig::default();c.damping_base=1e-20;c.damping_step=0.;c.validate().unwrap();let prefix=c.kernel_prefix();let line=prefix.lines().find_map(|line|line.strip_prefix("#define QUIP_DAMPING_BASE ")).unwrap();let emitted=line.strip_suffix('f').unwrap().parse::<f32>().unwrap();assert!(emitted>0.);assert_eq!(emitted.to_bits(),c.damping_base.to_bits());
    }
    #[test]
    fn kernel_configuration_changes_compilation_source() {
        let mut c=SearchConfig::default();c.replicas=256;c.minsum_replicas=None;c.damping_step=0.05;c.penalty_base=300.;c.validate().unwrap();
        let prefix=c.kernel_prefix();assert!(prefix.contains("#define QUIP_MINSUM_REPLICAS 84"));assert!(prefix.contains("#define QUIP_DAMPING_STEP"));assert!(prefix.contains("#define QUIP_PENALTY_BASE"));
        c.minsum_replicas=Some(0);c.validate().unwrap();assert!(c.kernel_prefix().contains("#define QUIP_MINSUM_REPLICAS 0"));
    }
    #[test]
    fn temperature_control_has_exact_default_and_cache_identity(){
        let default=SearchConfig::default();assert_eq!(default.temperature_milli,45.);assert!(default.kernel_prefix().is_empty());
        for t in [0.,-1.,f32::NAN,f32::INFINITY,10001.]{let mut c=default.clone();c.temperature_milli=t;assert!(c.validate().is_err());}
        for t in [15.,30.,60.,90.]{let mut c=default.clone();c.temperature_milli=t;c.validate().unwrap();let prefix=c.kernel_prefix();let line=prefix.lines().find_map(|l|l.strip_prefix("#define QUIP_TEMPERATURE ")).unwrap();assert_eq!(line.strip_suffix('f').unwrap().parse::<f32>().unwrap().to_bits(),t.to_bits());assert_ne!(prefix,default.kernel_prefix());}
        assert_eq!(search_config_from_patch(serde_json::json!({"temperature_milli":60})).unwrap().temperature_milli,60.);
    }
    #[test]fn seeded_ramp_has_exact_default_and_distinct_cache_source(){
        let d=SearchConfig::default();assert_eq!(d.seeded_ramp_scale,1.);assert!(d.kernel_prefix().is_empty());for v in [0.,-1.,f32::NAN,f32::INFINITY,101.]{let mut c=d.clone();c.seeded_ramp_scale=v;assert!(c.validate().is_err());}for v in [0.5,0.75,1.5,2.]{let mut c=d.clone();c.seeded_ramp_scale=v;c.validate().unwrap();assert!(c.kernel_prefix().contains("#define QUIP_SEEDED_RAMP_SCALE"));}assert_eq!(search_config_from_patch(serde_json::json!({"seeded_ramp_scale":0.5})).unwrap().seeded_ramp_scale,0.5);
    }
    #[test]fn weak_weight_is_runtime_data_and_validates_patch(){
        let d=SearchConfig::default();assert_eq!(d.weak_scale,1.);for v in [0.,-1.,f32::NAN,f32::INFINITY,8.1]{let mut c=d.clone();c.weak_scale=v;assert!(c.validate().is_err());}
        for v in [0.5,1.5,2.,8.]{let mut c=d.clone();c.weak_scale=v;c.validate().unwrap();assert_eq!(c.kernel_prefix(),d.kernel_prefix());}
        assert_eq!(search_config_from_patch(serde_json::json!({"weak_scale":1.5})).unwrap().weak_scale,1.5);
    }
    #[test]fn temporary_weak_scale_restores_nested_search_and_errors(){
        let original=weak_search_scale();{let _scope=WeakScaleScope::new(1.5).unwrap();assert_eq!(weak_search_scale(),1.5);{let _nested=WeakScaleScope::new(2.).unwrap();assert_eq!(weak_search_scale(),2.);}assert_eq!(weak_search_scale(),1.5);assert!(WeakScaleScope::new(f32::NAN).is_err());assert_eq!(weak_search_scale(),1.5);}assert_eq!(weak_search_scale(),original);
    }
